class DeleteWalletRecoveryPhraseView extends ConsumerStatefulWidget {
  const DeleteWalletRecoveryPhraseView({
    super.key,
    required this.walletId,
    required this.mnemonic,
    this.clipboardInterface = const ClipboardWrapper(),
  });

  static const routeName = "/deleteWalletRecoveryPhrase";

  final String walletId;
  final List<String> mnemonic;
  final ClipboardInterface clipboardInterface;

  @override
  ConsumerState<DeleteWalletRecoveryPhraseView> createState() =>
      _DeleteWalletRecoveryPhraseViewState();
}

class _DeleteWalletRecoveryPhraseViewState
    extends ConsumerState<DeleteWalletRecoveryPhraseView> {
  late List<String> _mnemonic;
  late ClipboardInterface _clipboardInterface;

  bool _lock = false;
  void _continuePressed() {
    if (_lock) {
      return;
    }
    _lock = true;
    try {
      showDialog<dynamic>(
        barrierDismissible: true,
        context: context,
        builder: (_) => StackDialog(
          title: l10n.walletWillBeDeleted,
          leftButton: TextButton(
            style: Theme.of(context)
                .extension<StackColors>()!
                .getSecondaryEnabledButtonStyle(context),
            onPressed: () {
              Navigator.pop(context);
            },
            child: Text(
              l10n.commonCancel,
              style: STextStyles.button(context).copyWith(
                color: Theme.of(context)
                    .extension<StackColors>()!
                    .accentColorDark,
              ),
            ),
          ),
          rightButton: TextButton(
            style: Theme.of(context)
                .extension<StackColors>()!
                .getPrimaryEnabledButtonStyle(context),
            onPressed: () async {
              await ref
                  .read(pWallets)
                  .deleteWallet(
                    ref.read(pWalletInfo(widget.walletId)),
                    ref.read(secureStoreProvider),
                  );

              if (mounted) {
                Navigator.of(context)
                    .popUntil(ModalRoute.withName(HomeView.routeName));
              }
            },
            child: Text(l10n.commonOk, style: STextStyles.button(context)),
          ),
        ),
      );
    } finally {
      _lock = false;
    }
  }

  @override
  void initState() {
    _mnemonic = widget.mnemonic;
    _clipboardInterface = widget.clipboardInterface;
    super.initState();
  }

  @override
  Widget build(BuildContext context) =>
      SecretScreen(child: Builder(builder: _buildScreen));

  Widget _buildScreen(BuildContext context) {
    debugPrint("BUILD: $runtimeType");

    return Background(
      child: Scaffold(
        backgroundColor: Theme.of(context).extension<StackColors>()!.background,
        appBar: AppBar(
          leading: AppBarBackButton(
            onPressed: () {
              Navigator.of(context).pop();
            },
          ),
          actions: [
            Padding(
              padding: const EdgeInsets.all(10),
              child: AspectRatio(
                aspectRatio: 1,
                child: AppBarIconButton(
                  color: Theme.of(context).extension<StackColors>()!.background,
                  shadows: const [],
                  icon: SvgPicture.asset(
                    Assets.svg.copy,
                    width: 20,
                    height: 20,
                    color: Theme.of(context)
                        .extension<StackColors>()!
                        .topNavIconPrimary,
                  ),
                  onPressed: () async {
                    await _clipboardInterface.setSecret(_mnemonic.join(" "));
                    if (context.mounted) {
                      unawaited(
                        showFloatingFlushBar(
                          type: FlushBarType.info,
                          message: l10n.commonCopiedToClipboard,
                          iconAsset: Assets.svg.copy,
                          context: context,
                        ),
                      );
                    }
                  },
                ),
              ),
            ),
          ],
        ),
        body: SafeArea(
          child: Padding(
            padding: const EdgeInsets.all(16),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                const SizedBox(height: 4),
                Text(
                  ref.watch(pWalletName(widget.walletId)),
                  textAlign: TextAlign.center,
                  style: STextStyles.label(context).copyWith(fontSize: 12),
                ),
                const SizedBox(height: 4),
                Text(
                  l10n.addWalletRecoveryPhraseTitle,
                  textAlign: TextAlign.center,
                  style: STextStyles.pageTitleH1(context),
                ),
                const SizedBox(height: 16),
                Container(
                  decoration: BoxDecoration(
                    color: Theme.of(context).extension<StackColors>()!.popupBG,
